            ["home.eyebrow"]="MACEDONIA · BEYOND THE ORDINARY",["home.heroTitleFirst"]="Don't just visit.",["home.heroTitleSecond"]="Discover.",["home.heroDescription"]="Hidden places. Local stories. Unforgettable experiences. Discover the side of Macedonia that most travelers never see.",["home.exploreHidden"]="Explore hidden places",["home.findAdventure"]="Find your adventure",["home.scrollExplore"]="SCROLL TO EXPLORE",["home.idea"]="The idea behind HIDDEN MK",["home.introTitle"]="There is more to Macedonia than the places on the map.",["home.introDescription"]="We believe the best journeys are not always found in guidebooks. HIDDEN MK connects curious travelers with remarkable landscapes, forgotten places, local traditions and experiences worth remembering.",["home.ourStory"]="Our story",["home.startExploring"]="Start exploring",["home.discoverDifferentFirst"]="Discover something",["home.discoverDifferentSecond"]="different.",["home.viewAllDestinations"]="View all destinations",["home.mountains"]="MOUNTAINS",["home.galicnikDescription"]="Stone houses, mountain air and stories that have survived generations.",["home.wildNature"]="WILD NATURE",["home.pelisterDescription"]="Ancient forests and trails above the clouds.",["home.waterNature"]="WATER & NATURE",["home.prespaDescription"]="Quiet shores, hidden paths and untouched views.",["home.canyons"]="CANYONS",["home.matkaDescription"]="Caves, cliffs and emerald water just outside the city.",["home.explore"]="Explore",["home.nextAdventure"]="Your next adventure",["home.whereNextFirst"]="Where should",["home.whereNextSecond"]="you go next?",["home.adventureDescription"]="Not sure where to start? Tell us what kind of experience you're looking for and we'll point you in the right direction.",["home.nature"]="Nature",["home.culture"]="Culture",["home.adventure"]="Adventure",["home.foodStories"]="Food & Stories",["home.travelDifferently"]="Travel differently",["home.goBeyondFirst"]="Go beyond",["home.goBeyondSecond"]="the 