            ["home.eyebrow"]="МАКЕДОНИЈА · НАДВОР ОД ВООБИЧАЕНОТО",["home.heroTitleFirst"]="Не само посетувај.",["home.heroTitleSecond"]="Откривај.",["home.heroDescription"]="Скриени места. Локални приказни. Незаборавни искуства. Откријте ја Македонија што повеќето патници никогаш не ја гледаат.",["home.exploreHidden"]="Откриј скриени места",["home.findAdventure"]="Пронајди ја твојата авантура",["home.scrollExplore"]="СКРОЛУВАЈ ЗА ДА ИСТРАЖУВАШ",["home.idea"]="Идејата зад HIDDEN MK",["home.introTitle"]="Македонија е многу повеќе од местата на мапата.",["home.introDescription"]="Веруваме дека најдобрите патувања не секогаш се наоѓаат во туристичките водичи. HIDDEN MK ги поврзува љубопитните патници со неверојатни пејзажи, заборавени места, локални традиции и искуства вредни за паметење.",["home.ourStory"]="Нашата приказна",["home.startExploring"]="Започни со истражување",["home.discoverDifferentFirst"]="Откриј нешто",["home.discoverDifferentSecond"]="поинакво.",["home.viewAllDestinations"]="Погледни ги сите дестинации",["home.mountains"]="ПЛАНИНИ",["home.galicnikDescription"]="Камени куќи, планински воздух и приказни што преживеале низ генерации.",["home.wildNature"]="ДИВА ПРИРОДА",["home.pelisterDescription"]="Древни шуми и патеки над облаците.",["home.waterNature"]="ВОДА И ПРИРОДА",["home.prespaDescription"]="Мирни брегови, скриени патеки и недопрени глетки.",["home.canyons"]="КАНЬОНИ",["home.matkaDescription"]="Пештери, карпи и смарагдно зелена вода надвор од градот.",["home.explore"]="Истражи",["home.nextAdventure"]="Твојата следна авантура",["home.whereNextFirst"]="Каде ќе",["home.whereNextSecond"]="одиш следно?",["home.adventureDescription"]="Не знаеш од каде да започнеш? Кажи ни какво искуство бараш и ќе те насочиме во вистинската насока.",["home.nature"]="Природа",["home.culture"]="Култура",["home.adventure"]="Авантура",["home.foodStories"]="Храна и приказни",["home.travelDifferently"]="Патувај поинаку",["home.goBeyondFirst"]="Оди подалеку",["home.goBeyondSecond"]="од очигледното.",["home.experienceDescription"]="HIDDEN MK е за луѓето кои би избрале планински пат, би разговарале со локалец и би откривале место полека, наместо само да штиклираат уште една дестинација од листата.",["home.curatedExperiences"]="Избрани искуства",["home.localGuides"]="Локални водичи",["home.authenticStories"]="Автентични приказни",["home.ofMany"]="од многуте",["home.stories"]="приказни",["home.hiddenPlaces"]="скриени места",["home.guides"]="локални водичи",["home.uniqueExperiences"]="уникатни искуства",["home.country"]="земја за откривање",["home.fromJournal"]="Од дневникот",["home.storiesRoadFirst"]="Приказни од",["home.storiesRoadSecond"]="патот.",["home.readAllStories"]="Прочитај ги сите приказни",["home.travelGuide"]="ТУРИСТИЧКИ ВОДИЧ · 8 МИН ЧИТАЊЕ",["home.localStories"]="ЛОКАЛНИ ПРИКАЗНИ · 6 МИН ЧИТАЊЕ",["home.food"]="ХРАНА · 5 МИН ЧИТАЊЕ",["home.readStory"]="Прочитај ја приказната",["home.story1"]="7 места во Македонија за кои веројатно не сте слушнале",["home.story2"]="Селата каде времето се движи поинаку",["home.story3"]="Вкус на Македонија: пет јадења вредни за патувањето",["home.yourStory"]="Твојата приказна започнува тука",["home.readyToDiscoverFirst"]="Подготвен да откриеш",["home.readyToDiscoverSecond"]="нешто скриено?",["home.finalDescription"]="Твоето следно незаборавно искуство можеби е поблиску отколку што мислиш.",["home.planAdventure"]="Испланирај ја твојата авантура",
            ["discover.eyebrow"]="ОТКРИЈ ГО HIDDEN MK",["discover.title"]="Започни со љубопитност.",["discover.subtitle"]="Следи ја кон нешто неочекувано.",["discover.beyond"]="НАДВОР ОД ОЧИГЛЕДНОТО",["discover.looking"]="Што барате?",["discover.lookingText"]="Без разлика дали барате тивка планинска патека, заборавено село, традиционално јадење или следната авантура, истражувајте ја Македонија преку работите што ве интересираат најмногу.",["discover.nature"]="Природа",["discover.natureText"]="Планини, езера, шуми, пештери и пејзажи што чекаат да бидат откриени.",["discover.exploreNature"]="Истражи ја природата",["discover.culture"]="Култура",["discover.cultureText"]="Села, традиции, историја и приказни што се пренесуваат од генерација на генерација.",["discover.discoverCulture"]="Откриј ја културата",["discover.food"]="Храна и локален живот",["discover.foodText"]="Традиционални јадења, локални производители и луѓето зад македонската гастрономска култура.",["discover.taste"]="Вкуси ја Македонија",["discover.adventure"]="Авантура",["discover.adventureText"]="Планинарење, кајакарење, кампување и искуства создадени за љубопитни истражувачи.",["discover.findAdventure"]="Пронајди авантура",["discover.how"]="КАКО ФУНКЦИОНИРА",["discover.howTitle"]="Откриј на свој начин.",["discover.howText"]="Не постои само еден начин да ја истражуваш Македонија. Избери нешто што те интересира и дозволи патувањето да те одведе понатаму.",["discover.step1"]="Избери што те интересира",["discover.step1Text"]="Природа, култура, храна или авантура — започни од онаму каде што те води љубопитноста.",["discover.step2"]="Истражи ги можностите",["discover.step2Text"]="Разгледај дестинации, искуства и приказни избрани од HIDDEN MK.",["discover.step3"]="Оди подалеку од водичот",["discover.step3Text"]="Избери нешто неочекувано и создај патување што навистина е твое.",["discover.start"]="ЗАПОЧНИ СО ИСТРАЖУВАЊЕ",["discover.places"]="Места каде вреди да се изгубиш.",["discover.viewAll"]="Погледни ги сите дестинации",["discover.finalEyebrow"]="НЕ ЗНАЕШ ОД КАДЕ ДА ЗАПОЧНЕШ?",["discover.finalTitle"]="Ние ќе ја најдеме твојата авантура.",["discover.finalText"]="Одговори на неколку едноставни прашања и откриј искуство што одговара на твојот стил.",
["story.1.title"]="7 места во Македонија за кои веројатно не сте слушнале",["story.1.category"]="Туристички водич",["story.1.excerpt"]="Покрај познатите езера и градови постои друга Македонија — потивка, подива и полна со изненадувања.",["story.1.author"]="HIDDEN MK Editorial",["story.1.date"]="12 септември 2026",["story.1.content"]="Македонија е мала земја со неверојатна разновидност на пејзажи. Покрај дестинациите што повеќето патници ги знаат, постојат планински села, скриени патеки, мирни езера и заборавени места што чекаат да бидат истражени.\n\nОд камените куќи на Галичник до мирните предели околу Преспа, најдобрите откритија често се случуваат кога ќе го напуштите главниот пат.\n\nВо HIDDEN MK веруваме дека патувањето е љубопитност. Одете по подолгиот пат, разговарајте со локалец и дозволете си малку да залутате.",["story.2.title"]="Селата каде времето се движи поинаку",["story.2.category"]="Локални приказни",["story.2.excerpt"]="Некои места не бараат да забавите. Тие само ве потсетуваат дека веќе сте забавиле.",["story.2.author"]="Елена Петрова",["story.2.date"]="28 август 2026",["story.2.content"]="Низ планините на Македонија има села каде традиционалната архитектура, храната и обичаите сè уште се дел од секојдневниот живот.\n\nГаличник, Лазарополе и други планински заедници нудат поглед во побавен ритам на животот. Камените куќи се сместени под огромни планински предели, додека локалните традиции продолжуваат да ги поврзуваат генерациите.\n\nЗа патниците, овие места нудат нешто што не може да се најде во конвенционална туристичка атракција: време да застанете и едноставно да бидете присутни.",["story.3.title"]="Вкус на Македонија: пет јадења вредни за патувањето",["story.3.category"]="Храна",["story.3.excerpt"]="Патувајте преку храната и откријте ги традициите зад некои од најомилените македонски јадења.",["story.3.author"]="Ана Стојановска",["story.3.date"]="14 август 2026",["story.3.content"]="Храната е еден од најлесните начини да се разбере едно место. Македонската кујна спојува едноставни состојки, рецепти стари со генерации и влијанија од целиот Балкан.\n\nАјвар, тавче гравче, зелник и свежо селско сирење се само дел од вкусовите што вреди да се откријат. Но вистинското искуство често доаѓа кога ги јадете таму каде што се подготвени.\n\nОброк подготвен од локално семејство може да стане еден од најнезаборавните делови од патувањето.",["story.4.title"]="Зошто патуваме подалеку од туристичкиот водич",["story.4.category"]="HIDDEN MK",["story.4.excerpt"]="Најнезаборавните патувања ретко следат список.",["story.4.author"]="HIDDEN MK Editorial",["story.4.date"]="30 јули 2026",["story.4.content"]="Патувањето се промени. Веќе не се работи само за гледање што е можно повеќе познати места. Сè повеќе патници бараат автентични искуства, локални врски и дестинации каде можат да забават.\n\nТаа идеја е во срцето на HIDDEN MK. Сакаме да им помогнеме на луѓето да откријат поинаква страна на Македонија — лична, неочекувана и вредна за паметење.",
            ["about.title"]="Македонија крие многу повеќе од она што го гледаме.",["about.eyebrow"]="ЗА HIDDEN MK",["about.intro"]="HIDDEN MK е платформа за откривање создадена за луѓе кои сакаат да ја доживеат  Македонија надвор од вообичаените туристички рути.",["about.storyEyebrow"]="НАШАТА ПРИКАЗНА",["about.storyTitle"]="Веруваме дека најдобрите места понекогаш најтешко се наоѓаат.",["about.story1"]="Македонија е мала земја со неверојатна разновидност на пејзажи, традиции, храна и приказни. Некои од најнезаборавните искуства се скриени подалеку од главните туристички рути.",["about.story2"]="HIDDEN MK е создаден за да ги доближи тие места до љубопитните патници — од планински села и заборавени патеки до локална храна, древни традиции и неочекувани авантури.",["about.story3"]="Не сакаме само да ви кажеме каде да одите. Сакаме да разберете зошто местото е важно.",["about.philosophy"]="НАШАТА ФИЛОЗОФИЈА",["about.philosophyText"]="Патувај побавно.<br />Гледај повнимателно.<br />Откриј повеќе.",["about.values"]="ШТО НИ Е ВАЖНО",["about.moreThan"]="Повеќе од дестинации.",["about.valuesIntro"]="HIDDEN MK се темели на идејата дека значајното патување е за луѓето, местата и приказните.",["about.value1Title"]="Автентично откривање",["about.value1"]="Гледаме подалеку од очигледното и истакнуваме места што нудат нешто навистина различно.",["about.value2Title"]="Локални приказни",["about.value2"]="Секоја дестинација има луѓе, традиции и приказни што вреди да се слушнат.",["about.value3Title"]="Почит кон природата",["about.value3"]="Поттикнуваме одговорно истражување и почит кон пејзажите што ги откриваме.",["about.idea"]="ИДЕЈАТА",["about.ideaTitle"]="Поинаков начин за истражување на Македонија.",["about.ideaText"]="HIDDEN MK ги спојува водичите за дестинации, локалните искуства и приказните на едно место. Без разлика дали ја планирате првата посета или живеете тука цел живот, секогаш има нешто ново за откривање.",
            ["team.title"]="Нашиот тим",["team.eyebrow"]="ЛУЃЕТО ЗАД HIDDEN MK",["team.heading"]="Запознајте го тимот.",["team.intro"]="Мал тим со голема љубопитност за местата, луѓето и приказните што ја прават Македонија уникатна.",["team.label"]="НАШИОТ ТИМ",["team.subtitle"]="Љубопитни луѓе. Различни перспективи.",["team.role1"]="ОСНОВАЧ И КРЕАТИВЕН ДИРЕКТОР",["team.bio1"]="Елена ги претвора заборавените места и локалните приказни во искуства вредни за паметење.",["team.role2"]="КУРАТОР ЗА ПАТУВАЊА И ИСКУСТВА",["team.bio2"]="Љубител на планините кој постојано ја бара следната патека, село или скриена глетка.",["team.role3"]="УРЕДНИК ЗА ХРАНА И КУЛТУРА",["team.bio3"]="Ана ја истражува Македонија преку нејзината храна, традиции и луѓето кои ги одржуваат живи.",["team.role4"]="ФОТОГРАФ И РАСКАЖУВАЧ",["team.bio4"]="Давид ги доловува пејзажите и малите моменти што секое патување го прават лично.",["team.join"]="САКАТЕ ДА СЕ ПРИДРУЖИТЕ?",["team.joinTitle"]="Имате скриено место за кое треба да знаеме?",["team.joinText"]="Секогаш бараме локални приказни, уникатни искуства и места што заслужуваат да бидат откриени.",["team.joinButton"]="Кажете ни за него",
